$id=(int)($_GET['id']??$_POST['id']??0);$tag=[];if($id){$q=db()->prepare('SELECT * FROM tags WHERE id=?');$q->execute([$id]);$tag=$q->fetch()?:[];if(!$tag){flash('error','برچسب پیدا نشد.');redirect('tags.php');}}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf_token']??null);try{$title=text_substr(trim((string)($_POST['title']??'')),0,80);$slug=strtolower(trim((string)($_POST['slug']??'')));$type=in_array(($_POST['tag_type']??''),['marketing','attribute'],true)?(string)$_POST['tag_type']:'marketing';$color=in_array(($_POST['color_key']??''),['primary','accent','sand','green','blue','neutral'],true)?(string)$_POST['color_key']:'primary';$icon=text_substr(trim((string)($_POST['icon']??'')),0,12);$sort=(int)en_digits((string)($_POST['sort_order']??0));$active=isset($_POST['active'])?1:0;$starts=parse_optional_jalali_datetime((string)($_POST['starts_date_j']??''),(string)($_POST['starts_time']??''),'شروع نمایش برچسب');$ends=parse_optional_jalali_datetime((string)($_POST['ends_date_j']??''),(string)($_POST['ends_time']??''),'پایان نمایش برچسب');if($title==='')throw new RuntimeException('عنوان برچسب را وارد کن.');if($slug==='')$slug='tag-'.bin2hex(random_bytes(4));if(!preg_match('/^[a-z0-9-]+$/',$slug))throw new RuntimeException('شناسه دستی فقط حروف انگلیسی کوچک، عدد و خط تیره باشد.');if($starts!==null&&$ends!==null&&strtotime($ends)<=strtotime($starts))throw new RuntimeException('زمان پایان باید بعد از شروع باشد.');$params=[$title,$slug,$type,$color,$icon?:null,$active,$sort,$starts,$ends];if($id){$params[]=$id;db()->prepare('UPDATE tags SET title=?,slug=?,tag_type=?,color_key=?,icon=?,active=?,sort_order=?,starts_at=?,ends_at=? WHERE id=?')->execute($params);}else{db()->prepare('INSERT INTO tags(title,slug,tag_type,color_key,icon,active,sort_order,starts_at,ends_at)VALUES(?,?,?,?,?,?,?,?,?)')->execute($params);}flash('success','برچسب ذخیره شد.');redirect('tags.php');}catch(PDOException){flash('error','شناسه برچسب تکراری است.');$tag=array_merge($tag,$_POST);}catch(Throwable $e){error_log('tag save: '.$e->getMessage());flash('error',safe_business_error_message($e,'ذخیره برچسب انجام نشد.'));$tag=array_merge($tag,$_POST);}}
